import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    system = platform.system()
    if system == "Windows":
        cmd = "wmic cpu get loadpercentage"
    else:
        cmd = "top -bn1 | grep 'Cpu(s)' | awk '{print $2}' | cut -d'%' -f1"
    records = []
    iterations = int(duration // interval)
    for i in range(iterations):
        timestamp = time.time()
        try:
            output = subprocess.check_output(cmd, shell=True).decode().strip()
            if system == "Windows":
                cpu_usage = float(output.split('\n')[1].strip())
            else:
                cpu_usage = float(output)
        except:
            cpu_usage = 0.0
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        if i < iterations - 1:
            time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

