import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    proc = subprocess.Popen(script_path, shell=True)
    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()
    while True:
        try:
            cpu_usage += p.cpu_percent(interval=0.0)
            memory_usage += p.memory_info().rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
        if not p.is_running():
            break
        if time.time() - start_time > timeout:
            proc.terminate()
            break
        time.sleep(0.1)
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

import subprocess
from ipaddress import IPv4Network
import sys
def task_func(ip_range):
    network = IPv4Network(ip_range, strict=False)
    if sys.platform.startswith('win'):
        ping_cmd = ['ping', '-n', '1', '-w', '1']
    else:
        ping_cmd = ['ping', '-c', '1', '-W', '1']
    result_dict = {}
    for ip in network.hosts():
        cmd = ping_cmd + [str(ip)]
        proc = subprocess.run(cmd, capture_output=True)
        if proc.returncode == 0:
            result_dict[str(ip)] = True
        elif proc.returncode == 1:
            result_dict[str(ip)] = False
        else:
            raise subprocess.CalledProcessError(proc.returncode, cmd)
    return result_dict
